import{_ as t,o as e,c as a,aw as o}from"./chunks/framework.DLufY-ao.js";const _=JSON.parse('{"title":"Системы управления версиями","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/main/git/theory/vcs.md","filePath":"wiki/dev-commit/main/git/theory/vcs.md"}'),r={name:"wiki/dev-commit/main/git/theory/vcs.md"};function l(s,i,n,c,m,d){return e(),a("div",null,[...i[0]||(i[0]=[o('<h1 id="системы-управления-версиями" tabindex="-1">Системы управления версиями <a class="header-anchor" href="#системы-управления-версиями" aria-label="Permalink to &quot;Системы управления версиями&quot;">​</a></h1><h2 id="типы" tabindex="-1">Типы <a class="header-anchor" href="#типы" aria-label="Permalink to &quot;Типы&quot;">​</a></h2><ul><li><strong>Централизованная система управления версиями</strong> (Version Control System, VCS или Revision Control System) - позволяет хранить несколько версий одного и того же документа, при необходимости возвращаться к более ранним версиям, определять, кто и когда сделал то или иное изменение, и многое другое</li><li>Такие системы наиболее широко используются при разработке программного обеспечения для хранения исходных кодов разрабатываемой программы</li><li>Традиционные системы управления версиями используют централизованную модель, когда имеется единое хранилище документов, управляемое специальным сервером, который и выполняет бо́льшую часть функций по управлению версиями</li><li>Контроль версий означает что вы храните все версии редактируемых документов и можете вернуться к любой сохраненной версии в любой момент времени</li><li>Примеры: SVN, Team Foundation Server</li><li><strong>Распределённые системы управления версиями</strong> (Distributed Version Control System, DVCS) - используют распределённую модель вместо традиционной клиент-серверной. Они, в общем случае, не нуждаются в централизованном хранилище: вся история изменения документов хранится на каждом компьютере, в локальном хранилище, и при необходимости отдельные фрагменты истории локального хранилища синхронизируются с аналогичным хранилищем на другом компьютере. В некоторых таких системах локальное хранилище располагается непосредственно в каталогах рабочей копии</li><li>Когда пользователь такой системы выполняет обычные действия, такие как извлечение определённой версии документа, создание новой версии и тому подобное, он работает со своей локальной копией хранилища. По мере внесения изменений, хранилища, принадлежащие разным разработчикам, начинают различаться, и возникает необходимость в их синхронизации. Такая синхронизация может осуществляться с помощью обмена патчами или так называемыми наборами изменений (англ. change sets) между пользователями.</li><li>С точки зрения пользователя распределённая система отличается необходимостью создавать локальный репозиторий и наличием в командном языке двух дополнительных команд: команды получения репозитория от удалённого компьютера (pull) и передачи своего репозитория на удалённый компьютер (push). Первая команда выполняет слияние изменений удалённого и локального репозиториев с помещением результата в локальный репозиторий; вторая — наоборот, выполняет слияние изменений двух репозиториев с помещением результата в удалённый репозиторий</li><li>Примеры: Git, Mercurial</li></ul><h2 id="общее" tabindex="-1">Общее <a class="header-anchor" href="#общее" aria-label="Permalink to &quot;Общее&quot;">​</a></h2><ul><li><strong>Git</strong> - распределенная система контроля версий (version control system - VCS)</li></ul>',5)])])}const u=t(r,[["render",l]]);export{_ as __pageData,u as default};
